-- @seq 344
CREATE FUNCTION public.ai_gateway_log(p_tenant_id uuid, p_feature text, p_model text, p_status_code integer, p_input_tokens integer, p_output_tokens integer, p_cost_usd numeric, p_latency_ms integer DEFAULT NULL::integer, p_provider_served text DEFAULT NULL::text, p_gateway_request_id text DEFAULT NULL::text, p_related_type text DEFAULT NULL::text, p_related_id uuid DEFAULT NULL::uuid, p_error text DEFAULT NULL::text, p_ai_task_id uuid DEFAULT NULL::uuid, p_cached_tokens integer DEFAULT 0) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_id uuid; s ai_gateway_settings%ROWTYPE; v_spent numeric; v_period text := to_char(now(),'YYYY-MM');
BEGIN
  IF NOT (platform_is_tenant_member(p_tenant_id) OR auth.role() = 'service_role') THEN
    RAISE EXCEPTION 'Not allowed for tenant %', p_tenant_id;
  END IF;
  INSERT INTO ai_gateway_requests(tenant_id, user_id, feature, model, provider_served, gateway_request_id, status_code, outcome,
         input_tokens, output_tokens, cached_tokens, cost_usd, latency_ms, related_type, related_id, error, ai_task_id)
  VALUES (p_tenant_id, auth.uid(), p_feature, p_model, p_provider_served, p_gateway_request_id, p_status_code,
          CASE WHEN p_status_code BETWEEN 200 AND 299 THEN 'ok' WHEN p_status_code = 402 THEN 'gateway_budget_exceeded'
               WHEN p_status_code = 408 OR p_status_code = 504 THEN 'timeout' ELSE 'error' END,
          coalesce(p_input_tokens,0), coalesce(p_output_tokens,0), coalesce(p_cached_tokens,0), coalesce(p_cost_usd,0),
          p_latency_ms, p_related_type, p_related_id, p_error, p_ai_task_id)
  RETURNING id INTO v_id;

  SELECT * INTO s FROM ai_gateway_settings WHERE tenant_id = p_tenant_id;
  IF FOUND AND s.monthly_budget_usd IS NOT NULL THEN
    SELECT coalesce(sum(cost_usd),0) INTO v_spent FROM ai_gateway_requests WHERE tenant_id = p_tenant_id AND created_at >= date_trunc('month', now());
    IF v_spent >= s.monthly_budget_usd * s.alert_at_percent / 100.0 THEN
      UPDATE ai_budget_alerts SET observed_spend = v_spent
       WHERE tenant_id = p_tenant_id AND period = v_period;
      IF NOT FOUND THEN
        INSERT INTO ai_budget_alerts(tenant_id, period, limit_usd, observed_spend, notified_count) VALUES (p_tenant_id, v_period, s.monthly_budget_usd, v_spent, 0);
      END IF;
    END IF;
  END IF;
  RETURN v_id;
END $$;

-- @seq 345
CREATE FUNCTION public.ai_gateway_preflight(p_tenant_id uuid, p_feature text, p_model text DEFAULT NULL::text) RETURNS TABLE(allowed boolean, model text, spent_usd numeric, budget_usd numeric, reason text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE s ai_gateway_settings%ROWTYPE; v_spent numeric; v_model text;
BEGIN
  IF NOT (platform_is_tenant_member(p_tenant_id) OR auth.role() = 'service_role') THEN
    RAISE EXCEPTION 'Not allowed for tenant %', p_tenant_id;
  END IF;
  SELECT * INTO s FROM ai_gateway_settings WHERE tenant_id = p_tenant_id;
  IF NOT FOUND THEN s.ai_enabled := true; s.allowed_models := '{}'; s.feature_models := '{}'; s.hard_stop := true; END IF;
  v_model := coalesce(p_model, s.feature_models->>p_feature, s.default_model, nullif(current_setting('app.ai_default_model', true), ''));
  IF v_model IS NULL THEN RETURN QUERY SELECT false, NULL::text, 0::numeric, s.monthly_budget_usd, 'No AI model configured (set ai_gateway_settings.default_model or app.ai_default_model)'; RETURN; END IF;
  SELECT coalesce(sum(cost_usd),0) INTO v_spent FROM ai_gateway_requests
   WHERE tenant_id = p_tenant_id AND created_at >= date_trunc('month', now());
  IF NOT s.ai_enabled THEN RETURN QUERY SELECT false, v_model, v_spent, s.monthly_budget_usd, 'AI is turned off for this company'; RETURN; END IF;
  IF cardinality(s.allowed_models) > 0 AND NOT (v_model = ANY (s.allowed_models)) THEN
    RETURN QUERY SELECT false, v_model, v_spent, s.monthly_budget_usd, 'Model not allowed: ' || v_model; RETURN;
  END IF;
  IF s.monthly_budget_usd IS NOT NULL AND s.hard_stop AND v_spent >= s.monthly_budget_usd THEN
    RETURN QUERY SELECT false, v_model, v_spent, s.monthly_budget_usd, 'Monthly AI budget reached'; RETURN;
  END IF;
  RETURN QUERY SELECT true, v_model, v_spent, s.monthly_budget_usd, NULL::text;
END $$;

