CREATE FUNCTION public.ai_intent_events_no_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'ai_intent_events is append-only: % is not permitted', TG_OP;
END;
$$;

